1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
30	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
31	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
32	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
35	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
46	     * when a non-blank title is present, or just the last name when no title was supplied.
47	     *
48	     * @param owner the owner to derive the salutation for
49	     * @return the composed salutation
50	     */
51	    default String salutation(Owner owner) {
52	        String title = owner.getTitle();
53	        String lastName = owner.getLastName();
54	        if (title == null || title.isBlank()) {
55	            return lastName;
56	        }
57	        return title + " " + lastName;
58	    }
59	
60	    /**
61	     * Derives an owner's age band from its birth date, computed as the owner's age on its
62	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
63	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
64	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
65	     * response.
66	     *
67	     * @param owner the owner to derive the age band for
68	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
69	     *     is held
70	     */
71	    default String ageBand(Owner owner) {
72	        java.time.LocalDate birthDate = owner.getBirthDate();
73	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
74	        if (birthDate == null || registrationDate == null) {
75	            return null;
76	        }
77	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
78	        if (age < 18) {
79	            return "MINOR";
80	        }
81	        return age < 65 ? "ADULT" : "SENIOR";
82	    }
83	
84	    /**
85	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
86	     * email, otherwise {@code "PHONE"}.
87	     *
88	     * @param owner the owner to derive the contact preference for
89	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
90	     */
91	    default String contactPreference(Owner owner) {
92	        String email = owner.getEmail();
93	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
94	    }
95	
96	    /**
97	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
98	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
99	     * normalizing telephones into E.164 form.
100	     */
101	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
102	
103	    /**
104	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
105	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
106	     * The country code is taken as the longest recognized prefix (see
107	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
108	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
109	     * is returned unchanged.
110	     *
111	     * @param owner the owner to format the telephone display for
112	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
113	     *     digit string
114	     */
115	    default String telephoneDisplay(Owner owner) {
116	        String telephone = owner.getTelephone();
117	        if (telephone == null || !telephone.startsWith("+")) {
118	            return telephone;
119	        }
120	        String digits = telephone.substring(1);
121	        if (!digits.matches("[0-9]+")) {
122	            return telephone;
123	        }
124	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
125	            .filter(digits::startsWith)
126	            .max(java.util.Comparator.comparingInt(String::length))
127	            .orElseGet(() -> digits.substring(0, 1));
128	        String national = digits.substring(countryCode.length());
129	        StringBuilder sb = new StringBuilder("+").append(countryCode);
130	        for (int i = 0; i < national.length(); i += 3) {
131	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
132	        }
133	        return sb.toString();
134	    }
135	
136	    /**
137	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
138	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
139	     * the customer code's region is itself derived from the postcode (falling back to the city), the
140	     * locality now moves with the identity rather than being computed independently. The result is
141	     * {@code "UNKNOWN"} when no customer code is present.
142	     *
143	     * @param owner the owner to derive the locality for
144	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
145	     */
146	    default String locality(Owner owner) {
147	        String code = owner.getCustomerCode();
148	        if (code == null || code.isEmpty()) {
149	            return "UNKNOWN";
150	        }
151	        int dash = code.indexOf('-');
152	        return dash < 0 ? code : code.substring(0, dash);
153	    }
154	
155	    /**
156	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
157	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
158	     */
159	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
160	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
161	
162	    /**
163	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
164	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
165	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
166	     * the field is omitted from the response.
167	     *
168	     * @param owner the owner to derive the timezone for
169	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
170	     */
171	    default String timezone(Owner owner) {
172	        return REGION_TIMEZONES.get(locality(owner));
173	    }
174	
175	    /**
176	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
177	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
178	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
179	     * than {@code 365} days - the number of days between the owner's registration date and the
180	     * current server date. Because a newly created owner registers on the current date, its tenure
181	     * is zero, so a new owner never earns the tenure points.
182	     *
183	     * @param owner the owner to derive the membership points for
184	     * @return the membership points, {@code 0} or more
185	     */
186	    default Integer membershipPoints(Owner owner) {
187	        int points = 0;
188	        String email = owner.getEmail();
189	        if (email != null && !email.isBlank()) {
190	            points += 2;
191	        }
192	        Integer namesakeCount = owner.getNamesakeCount();
193	        if (namesakeCount != null && namesakeCount == 0) {
194	            points += 1;
195	        }
196	        Integer householdMemberCount = owner.getHouseholdMemberCount();
197	        if (householdMemberCount != null && householdMemberCount >= 3) {
198	            points += 2;
199	        }
200	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
201	        long tenureDays = registrationDate == null ? 0
202	            : java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
203	        if (tenureDays > 365) {
204	            points += 3;
205	        }
206	        return points;
207	    }
208	
209	    /**
210	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
211	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
212	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more.
213	     *
214	     * @param owner the owner to derive the membership level for
215	     * @return the membership level, between {@code 1} and {@code 4}
216	     */
217	    default Integer membershipLevel(Owner owner) {
218	        int points = membershipPoints(owner);
219	        if (points <= 1) {
220	            return 1;
221	        }
222	        if (points <= 3) {
223	            return 2;
224	        }
225	        if (points <= 5) {
226	            return 3;
227	        }
228	        return 4;
229	    }
230	
231	    /**
232	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
233	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
234	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
235	     *
236	     * @param owner the owner to derive the membership number for
237	     * @return the formatted membership number
238	     */
239	    default String membershipNumber(Owner owner) {
240	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
241	        return owner.getCustomerCode() + "-M" + yy;
242	    }
243	
244	    /**
245	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
246	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
247	     * are ignored.
248	     *
249	     * @param owner the owner to derive the check digit for
250	     * @return the Luhn check digit, between {@code 0} and {@code 9}
251	     */
252	    default Integer checkDigit(Owner owner) {
253	        String code = owner.getCustomerCode();
254	        int sum = 0;
255	        boolean dbl = true;
256	        for (int i = code.length() - 1; i >= 0; i--) {
257	            char c = code.charAt(i);
258	            if (c < '0' || c > '9') {
259	                continue;
260	            }
261	            int d = c - '0';
262	            if (dbl) {
263	                d *= 2;
264	                if (d > 9) {
265	                    d -= 9;
266	                }
267	            }
268	            sum += d;
269	            dbl = !dbl;
270	        }
271	        return (10 - (sum % 10)) % 10;
272	    }
273	
274	    /**
275	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
276	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
277	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
278	     * string. Because it is derived deterministically from the last name and postcode, every owner
279	     * that shares those two fields receives the same value - including owners created via the
280	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
281	     *
282	     * @param owner the owner to derive the household identifier for
283	     * @return the 12 upper-case hex character household identifier, never blank
284	     */
285	    default String householdId(Owner owner) {
286	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
287	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
288	        try {
289	            byte[] digest = MessageDigest.getInstance("SHA-256")
290	                .digest(key.getBytes(StandardCharsets.UTF_8));
291	            StringBuilder sb = new StringBuilder(12);
292	            for (int i = 0; i < 6; i++) {
293	                sb.append(String.format("%02X", digest[i]));
294	            }
295	            return sb.toString();
296	        }
297	        catch (NoSuchAlgorithmException ex) {
298	            throw new IllegalStateException("SHA-256 not available", ex);
299	        }
300	    }
301	
302	    /**
303	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
304	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
305	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
306	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
307	     * whole identity keys are equal; because the telephone is part of the key, household members with
308	     * different telephones have different keys.
309	     *
310	     * @param owner the owner to derive the identity key for
311	     * @return the {@code telephone|email|householdId} identity key
312	     */
313	    default String identityKey(Owner owner) {
314	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
315	        String email = owner.getEmail() == null ? "" : owner.getEmail();
316	        return telephone + '|' + email + '|' + householdId(owner);
317	    }
318	
319	    /**
320	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
321	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
322	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
323	     *
324	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
325	     * conversion and apply it to unrelated String properties (last name, address, ...).
326	     */
327	    private String normalizeHouseholdField(String value) {
328	        if (value == null) {
329	            return "";
330	        }
331	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
332	    }
333	
334	    Owner toOwner(OwnerDto ownerDto);
335	
336	    @Mapping(target = "id", ignore = true)
337	    @Mapping(target = "pets", ignore = true)
338	    Owner toOwner(OwnerFieldsDto ownerDto);
339	
340	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
341	
342	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
343	
344	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
345	        OwnerPageDto ownerPageDto = new OwnerPageDto();
346	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
347	        ownerPageDto.setPage(ownerPage.getNumber());
348	        ownerPageDto.setSize(ownerPage.getSize());
349	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
350	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
351	        return ownerPageDto;
352	    }
353	}
